<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> i, bbox </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> enumerate</span><span style="color:#ABB2BF;">(bboxes):</span></span>
