<span class="line"><span style="color:#ABB2BF;">        rect </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> d2l.</span><span style="color:#61AFEF;">bbox_to_rect</span><span style="color:#ABB2BF;">(d2l.</span><span style="color:#61AFEF;">numpy</span><span style="color:#ABB2BF;">(bbox), color)</span></span>
