<span class="line"><span style="color:#ABB2BF;">    keep </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> []  </span><span style="color:#7F848E;font-style:italic;"># 保留预测边界框的指标</span></span>
