<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> nms</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">boxes</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">scores</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">iou_threshold</span><span style="color:#ABB2BF;">):</span></span>
